<?php require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('wallet','view');global $conn;$tenantId=(int)getCurrentTenantId();$balance=0;$q=$conn->prepare("SELECT COALESCE(balance,0) balance FROM tenant_wallets WHERE tenant_id=? LIMIT 1");if($q){$q->bind_param('i',$tenantId);$q->execute();$r=$q->get_result()->fetch_assoc();if($r)$balance=(float)$r['balance'];$q->close();}$pageTitle='Tenant Wallet';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Tenant Wallet</h2><div class="stat-card"><h3><?=e(formatMoney($balance))?></h3><p>Available Balance</p></div><p><a href="transactions.php">View Wallet Transactions</a></p></div><?php require_once '../includes/footer.php';?>